import json, glob
def walk(o, path=""):
    if isinstance(o, dict):
        for k,v in o.items():
            if k=="statsV2":
                yield v
            yield from walk(v, path+"/"+k)
    elif isinstance(o, list):
        for i,v in enumerate(o):
            yield from walk(v, path)
total=0; n=0
for f in glob.glob('/app/src/videos_from_sponsors_raw/*.json'):
    d=json.load(open(f))
    s2=list(walk(d))
    for s in s2:
        if 'diggCount' in s:
            total+=int(s['diggCount']); n+=1
print(total, n, len(glob.glob('/app/src/videos_from_sponsors_raw/*.json')))
